/* ------------------------------------------------------------------ */
/*  STAR PLAY — the majestic deck of 1,443 arcana (666 + 777).         */
/*  37 constellations × 39 movements, with the 24 handcrafted elder    */
/*  arcana folded into their matching slots. Deterministically         */
/*  composed (do not edit by hand — run scripts/compose-star-play-deck */
/*  .mjs to regenerate). Every card carries its own AI impression at   */
/*  {image}, derived from its constellation's bespoke master.          */
/*  Card text is oracle data (like the OS formulas) — the AI reading    */
/*  is composed in the visitor's language by /api/star-play.            */
/* ------------------------------------------------------------------ */

export interface ArcanaCard {
  id: string;
  name: string;
  essence: string;
  glyph: string;
  message: string;
  /** The card's own light — a desaturated gradient duo. */
  from: string;
  to: string;
  /** The constellation the card belongs to (selects its AI master). */
  realm: string;
  /** The card's own AI impression (derived, seeded per card). */
  image: string;
}

